var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3a_scen.gd")
GameState.state.meta["active_player"] = 2
H.shift("U_INFILTRATOR_SQUAD_A", -10.0, 0.0)
H.shift("U_INCURSOR_SQUAD_A", 3.0, 4.0)
var wb = H.unit("U_WARBIKERS_A")
var c := Vector2.ZERO
for m in wb.models:
	c += H._pos(m)
c /= float(wb.models.size())
H.shift("U_WARBIKERS_A", 30.0 - c.x / 40.0, 46.0 - c.y / 40.0)
PhaseManager.transition_to_phase(7)
return int(GameState.get_current_phase())

